const test = require("node:test");
const assert = require("node:assert");

const { startServer, api } = require("./helpers");

test("every error keeps the exact { error: message } contract", async () => {
  const { base, close } = startServer();
  try {
    const missing404 = await api(base, "GET", "/api/links/nope");
    assert.strictEqual(missing404.status, 404);
    assert.deepStrictEqual(missing404.json, { error: "link not found" });

    assert.deepStrictEqual((await api(base, "GET", "/r/nope")).json, { error: "link not found" });
    assert.deepStrictEqual(
      (await api(base, "GET", "/api/links/nope/stats")).json,
      { error: "link not found" },
    );
    assert.deepStrictEqual(
      (await api(base, "DELETE", "/api/links/nope")).json,
      { error: "link not found" },
    );

    const noUrl = await api(base, "POST", "/api/links", {});
    assert.strictEqual(noUrl.status, 400);
    assert.deepStrictEqual(noUrl.json, { error: "url is required" });

    const badSlug = await api(base, "POST", "/api/links", { url: "https://x.dev", slug: "NO" });
    assert.strictEqual(badSlug.status, 400);
    assert.deepStrictEqual(badSlug.json, { error: "invalid slug" });

    await api(base, "POST", "/api/links", { url: "https://x.dev", slug: "taken" });
    const dup = await api(base, "POST", "/api/links", { url: "https://y.dev", slug: "taken" });
    assert.strictEqual(dup.status, 409);
    assert.deepStrictEqual(dup.json, { error: "slug already taken" });
  } finally {
    await close();
  }
});

test("success paths unchanged", async () => {
  const { base, close } = startServer();
  try {
    const created = await api(base, "POST", "/api/links", { url: "https://ok.dev", slug: "fine" });
    assert.strictEqual(created.status, 201);
    assert.strictEqual((await api(base, "GET", "/r/fine")).status, 302);
    assert.strictEqual((await api(base, "DELETE", "/api/links/fine")).status, 204);
  } finally {
    await close();
  }
});

